CREATE SCHEMA IF NOT EXISTS trip_private;
GRANT USAGE ON SCHEMA trip_private TO authenticated;
ALTER FUNCTION public.is_trip_member(uuid,uuid) SET SCHEMA trip_private;
ALTER FUNCTION public.create_trip(text,text,date,date,text) SET SCHEMA trip_private;
ALTER FUNCTION public.join_trip(text) SET SCHEMA trip_private;
ALTER FUNCTION public.edit_trip(uuid,text,text,date,date) SET SCHEMA trip_private;
ALTER FUNCTION public.manage_trip_member(uuid,uuid,text) SET SCHEMA trip_private;
ALTER FUNCTION public.reset_trip_code(uuid) SET SCHEMA trip_private;
ALTER FUNCTION public.leave_trip(uuid) SET SCHEMA trip_private;
ALTER FUNCTION public.trip_roster(uuid) SET SCHEMA trip_private;
ALTER FUNCTION public.new_trip_code() SECURITY INVOKER;
CREATE FUNCTION public.is_trip_member(p_trip uuid,p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.is_trip_member(p_trip,p_user) $$;
REVOKE ALL ON FUNCTION public.is_trip_member(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_trip_member(uuid,uuid) TO authenticated;
CREATE FUNCTION public.create_trip(p_name text,p_destination text,p_start_date date,p_end_date date,p_home_timezone text) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.create_trip(p_name,p_destination,p_start_date,p_end_date,p_home_timezone) $$;
REVOKE ALL ON FUNCTION public.create_trip(text,text,date,date,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_trip(text,text,date,date,text) TO authenticated;
CREATE FUNCTION public.join_trip(p_code text) RETURNS uuid LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.join_trip(p_code) $$;
REVOKE ALL ON FUNCTION public.join_trip(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.join_trip(text) TO authenticated;
CREATE FUNCTION public.edit_trip(p_trip uuid,p_name text,p_destination text,p_start_date date,p_end_date date) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.edit_trip(p_trip,p_name,p_destination,p_start_date,p_end_date) $$;
REVOKE ALL ON FUNCTION public.edit_trip(uuid,text,text,date,date) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.edit_trip(uuid,text,text,date,date) TO authenticated;
CREATE FUNCTION public.manage_trip_member(p_trip uuid,p_user uuid,p_action text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.manage_trip_member(p_trip,p_user,p_action) $$;
REVOKE ALL ON FUNCTION public.manage_trip_member(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.manage_trip_member(uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.reset_trip_code(p_trip uuid) RETURNS text LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.reset_trip_code(p_trip) $$;
REVOKE ALL ON FUNCTION public.reset_trip_code(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reset_trip_code(uuid) TO authenticated;
CREATE FUNCTION public.leave_trip(p_trip uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = public AS $$ SELECT trip_private.leave_trip(p_trip) $$;
REVOKE ALL ON FUNCTION public.leave_trip(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.leave_trip(uuid) TO authenticated;
CREATE FUNCTION public.trip_roster(p_trip uuid) RETURNS TABLE(user_id uuid,role text,display_name text,avatar_url text,joined_at timestamptz) LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT * FROM trip_private.trip_roster(p_trip) $$;
REVOKE ALL ON FUNCTION public.trip_roster(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.trip_roster(uuid) TO authenticated;